validator:
function validate(input) {
  const [{ Wineries = [] }] = input;
  const ids = new Set();
  for (const [id, country, points, winery] of Wineries) {
    if (id === null) return 'Every row needs an id.';
    if (ids.has(id)) return `id ${id} appears twice.`;
    ids.add(id);
    if (country === null || winery === null) return `Row ${id} needs a country and a winery.`;
    if (!Number.isInteger(points) || points < 0) return `Row ${id} needs non-negative integer points.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const countries = small ? ['Australia', 'Hungary', 'India', 'USA'] : Array.from({ length: 30 }, (_, i) => `Country${String(i).padStart(2, '0')}`);
  const wineries = small ? ['GrapesGalore', 'HarmonyHill', 'MoonlitCellars', 'PacificCrest', 'RoyalVines'] : Array.from({ length: 60 }, (_, i) => `Winery${String(i).padStart(2, '0')}`);
  // Small cases reuse a few point values so winery totals tie and the name order decides.
  const points = [0, 10, 20, 30, 50];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Wineries = [];
  for (let i = 0; i < count; i++) Wineries.push([small ? 100 + i * 37 : i + 1, pick(countries), small ? pick(points) : Math.floor(rand() * 101), pick(wineries)]);
  return [{ Wineries }];
}
